  "certa": "A instalação In absentia mostra a sombra de uma roda de bicicleta no espaço, em diálogo com o ready-made de Duchamp, que transforma objetos comuns em obra de arte e critica o sistema da arte. A obra mostra que as criações desmistificam os valores estéticos estabelecidos.",
