  "certa": "O carro que chegou em último é o da reta de menor inclinação (velocidade constante), que termina no maior tempo. As curvas dos demais cruzam essa reta, e quem faz as ultrapassagens são os outros carros, que vão passando por ele. O carro da reta não ultrapassa nenhum: 0 ultrapassagens.",
